contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOperator, uint32 pId, address token, address rewards, address otherCaller) public {
        // owner (this contract) sets the operator and pool info
        c.setOperator(newOperator);
        c.setCvxPoolInfo(pId, token, rewards);

        // public getters must reflect exactly the values that were set
        assert(c.operator() == newOperator);
        (address gotToken, address gotRewards, uint32 gotPId) = c.cvxPoolInfo();
        assert(gotToken == token && gotRewards == rewards && gotPId == pId);

        // only the current operator may call depositAndStake
        bool revertedOther;
        address prev = c.operator();
        if (otherCaller != prev) {
            try c.depositAndStake(1) { revertedOther = false; } catch { revertedOther = true; }
            // this contract is the owner but NOT the operator, so it must revert
            assert(revertedOther);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOperator) public {
        // This contract is the owner (it deployed c); set the operator.
        c.setOperator(newOperator);

        // If the chosen caller is not the operator, depositAndStake must revert;
        // if it is the operator, it must not revert (reverts are impossible here only
        // if cvxPoolInfo.rewards is set, so just check the non-operator side).
        bool reverted;
        if (newOperator != address(this)) {
            try c.depositAndStake(0) { reverted = false; } catch { reverted = true; }
        }

        assert(
            (newOperator == address(this)) ||
            (c.operator() == newOperator && reverted)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // Only a zero-amount, zero-recipient withdrawal is exercised: it must
        // short-circuit both the unstake path (toUnstake == 0) and the transfer
        // path (to == address(0)), so it must never revert even though the
        // cvxPoolInfo rewards address is unset.
        require(amount == 0);

        bool reverted;
        try c.withdrawAndUnwrap(amount, false, address(0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && c.owner() == address(this));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool renounce) public {
        require(renounce);

        // The test contract is the owner of the freshly deployed c, so
        // renouncing must succeed and transfer ownership to the zero address.
        bool renounced;
        try c.renounceOwnership() {
            renounced = false;
        } catch {
            renounced = true;
        }

        // Once ownership is renounced, no caller is the owner anymore, so any
        // owner-only function must revert for everyone (including the previous
        // owner, i.e. this test contract).
        bool setterReverted;
        try c.setOperator(address(0x1)) {
            setterReverted = false;
        } catch {
            setterReverted = true;
        }

        assert(renounced && !setterReverted || !renounced && setterReverted || (renounced && c.owner() == address(0) && setterReverted));
        assert(renounced && c.owner() == address(0) && setterReverted);
    }

    receive() external payable {}
}

