contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address firstOperator, address newOperator) public {
        require(newOperator != address(0), "newOperator must be non-zero");
        // set an initial operator (owner is this test contract)
        c.setOperator(firstOperator);
        address before = c.operator();
        // deciding call: owner changes the operator
        c.setOperator(newOperator);
        address after_ = c.operator();
        // general rule: setOperator always sets operator() to exactly the given address
        assert(after_ == newOperator && (before == firstOperator || after_ == before));
    }
}

