contract InvMutTest {
    C c;

    // Observer values captured by the ERC20 stub (this contract acts as the token).
    address lastTransferTo;
    uint256 lastTransferAmount;
    uint256 transferCallCount;

    constructor(C _c) { c = _c; }

    function run(address token, address to, uint256 amount) public payable {
        require(token == address(this), "token must be the stub");
        require(to == address(this), "recipient must be the stub");

        // We are the owner of c (c was deployed with this contract as msg.sender).
        // Owner calls recoverToken: it must do IERC20(token).safeTransfer(to, amount)
        // and not revert when the token accepts the transfer.
        bool reverted;
        try c.recoverToken(token, to, amount) { reverted = false; } catch { reverted = true; }

        assert(
            !reverted &&
            transferCallCount == 1 &&
            lastTransferTo == to &&
            lastTransferAmount == amount
        );
    }

    // Minimal ERC20 stub: respond to transfer(address,uint256) with true,
    // recording the recipient and amount that c requested to move.
    fallback(bytes calldata input) external returns (bytes memory) {
        if (input.length == 68 && bytes4(input[0:4]) == bytes4(keccak256("transfer(address,uint256)"))) {
            address to;
            uint256 value;
            assembly {
                to := shr(96, calldataload(4))
                value := calldataload(36)
            }
            lastTransferTo = to;
            lastTransferAmount = value;
            transferCallCount++;
            return abi.encode(true);
        }
        revert("stub: unsupported");
    }

    receive() external payable {}
}

